  'DSC_4468.jpg': { title: 'Ferrari 296 Challenge #9 — Le Mans 2026', caption: 'The #9 Ferrari 296 Challenge in green camouflage livery for Henny\'s Restaurant and Events accelerates past a marshal post showing the full course yellow board.' },
