  'DSC_4472.jpg': { title: 'Ferrari 296 Challenge #277 Side Profile — Le Mans 2026', caption: 'A side view of the #277 Graypaul Ferrari 296 Challenge for e-ppl Group, showing the full Ferrari Challenge series decal above the door and the driver name P. Simmerson on the roof surround.' },
