  'DSC_5775.jpg': { title: 'BMW M3 (F80) on Circuit — Bimmerfest, Mondello Park', caption: 'The dark blue BMW M3 (F80) on circuit at Bimmerfest, Mondello Park.' },
  'DSC_5777.jpg': { title: 'SEAT Leon Cupra — Bimmerfest, Mondello Park', caption: 'A white SEAT Leon Cupra, driver in helmet, on circuit at Bimmerfest, Mondello Park.' },
