  'DSC_6247-Enhanced-NR.jpg': { title: "Toyota Celica, Retrostock", caption: "A clean white Toyota Celica on track during Retrostock. The classic white rally-style wheels and pop-up headlights bring plenty of nineties nostalgia to Mondello Park." },
  'DSC_6248-Enhanced-NR.jpg': { title: "Ford Sierra Cosworth, Retrostock", caption: "A red Ford Sierra Cosworth on track during Retrostock. The car features yellow headlight covers and Munster Refrigeration Services branding on the front splitter." },
